22	// The tests of Provision (DEVDESK-504, step 6) run it against the in-memory
23	// Nexus of fakenexus_test.go, with a fake SecretStore and a fake InitialPassword.
24	// Provision is called as
25	//
26	//	Provision(ctx, baseURL, ip, store, p, out) (ProvisionResult, error)
27	//
28	// The REST payloads are hypotheses (H-REST), centralized in fakenexus_test.go.
29	// Hypotheses specific to these tests, to settle at step 10 or with the code:
30	//   - a version is read from the Server header "Nexus/<version> (<EDITION>)";
31	//   - a generated password is 32 characters of [A-Za-z0-9];
32	//   - a refused redirect and an HTTP failure surface as an *APIError reachable
33	//     with errors.As, inside a *BenchError of kind ProvisionFailed; a transport
34	//     failure is a *BenchError of kind RESTUnreachable;
35	//   - the unknown admin password error says "admin password is unknown" and
36	//     names "mise run nexus-bench:down".
37	
38	const (
39		// storedAdmin is the admin password an earlier run stored.
40		storedAdmin = secretMarker + "-stored-admin"
41	
42		provisionTimeout = 30 * time.Second
43		mib              = 1 << 20
44	
45		groupRepository = "docker-group"
46	)
47	
48	const generatedAlphabet = "REDACTED"
49	
50	// ---- doubles ----------------------------------------------------------------
51	
52	var (
53		errFakeSave = errors.New("fake store: disk full")
54		errFakeRead = errors.New("fake initial password: exec refused")
55	)
56	
57	// memStore is a SecretStore in memory. It logs every Save in the shared journal
58	// ("STORE Save admin pending pull", only the non-empty fields) and can refuse
59	// some of them.
60	type memStore struct {
61		mu       sync.Mutex
62		log      *orderLog
63		secrets  Secrets
64		found    bool
65		failSave func(Secrets) bool
66		attempts []Secrets // every Save call, refused ones included
67	}
68	
69	var _ SecretStore = (*memStore)(nil)
70	
71	func (s *memStore) Load() (Secrets, bool, error) {
72		s.mu.Lock()
73		defer s.mu.Unlock()
74		return s.secrets, s.found, nil
75	}
76	
77	func (s *memStore) Save(sec Secrets) error {
78		s.mu.Lock()
79		defer s.mu.Unlock()
80		entry := "STORE Save"
81		for _, field := range []struct{ name, value string }{
82			{"admin", sec.AdminPassword}, {"pending", sec.PendingAdminPassword}, {"pull", sec.PullPassword},
83		} {
84			if field.value != "" {
85				entry += " " + field.name
86			}
87		}
88		s.log.add(entry)
89		s.attempts = append(s.attempts, sec)
90		if s.failSave != nil && s.failSave(sec) {
91			return errFakeSave
92		}
93		s.secrets, s.found = sec, true
94		return nil
95	}
96	
97	func (s *memStore) Remove() error {
98		s.mu.Lock()
99		defer s.mu.Unlock()
100		s.secrets, s.found = Secrets{}, false
101		return nil
102	}
103	
104	// preset stores secrets as an earlier run (or a hand edit) left them.
105	func (s *memStore) preset(sec Secrets) {
106		s.mu.Lock()
107		defer s.mu.Unlock()
108		s.secrets, s.found = sec, true
109	}
110	
111	// current returns what the store holds now.
112	func (s *memStore) current() Secrets {
113		s.mu.Lock()
114		defer s.mu.Unlock()
115		return s.secrets
116	}
117	
118	// values returns every non-empty password the store was ever asked to keep.
119	func (s *memStore) values() []string {
120		s.mu.Lock()
121		defer s.mu.Unlock()
122		var out []string
123		for _, sec := range append(slices.Clone(s.attempts), s.secrets) {
124			for _, v := range []string{sec.AdminPassword, sec.PendingAdminPassword, sec.PullPassword} {
125				if v != "" {
126					out = append(out, v)
127				}
128			}
129		}
130		return out
131	}
132	
133	// fakeInitial is the InitialPassword of the pod: the content of
134	// /nexus-data/admin.password while it exists.
135	type fakeInitial struct {
136		password string
137		ok       bool
138		err      error
139		reads    int
140	}
141	
142	var _ InitialPassword = REDACTED
143	
144	func (i *fakeInitial) Read(context.Context) (string, bool, error) {
145		i.reads++
146		if i.err != nil {
147			return "", false, i.err
148		}
149		return i.password, i.ok, nil
150	}
