152	// bench is one scenario: a fake instance, a fake store, a fake pod file.
153	type bench struct {
154		t     *testing.T
155		log   *orderLog
156		nexus *fakeNexus
157		store *memStore
158		ip    *fakeInitial
159		out   *bytes.Buffer
160		p     Params
161	}
162	
163	// newBench is a fresh instance with the initial admin password still in the pod,
164	// nothing stored, and the EULA accepted by the operator.
165	func newBench(t *testing.T) *bench {
166		t.Helper()
167		log := &orderLog{}
168		p := Defaults()
169		p.AcceptEULA = true
170		p.UpstreamURL = "http://upstream.bench.invalid:5000"
171		return &bench{
172			t:     t,
173			log:   log,
174			nexus: newFakeNexus(t, log),
175			store: &memStore{log: log},
176			ip:    &fakeInitial{password: REDACTED, ok: true},
177			out:   &bytes.Buffer{},
178			p:     p,
179		}
180	}
181	
182	// withKnownAdmin is an instance whose admin password an earlier run changed and
183	// stored: the pod file is gone.
184	func (b *bench) withKnownAdmin() *bench {
185		b.nexus.SetAdminPassword(storedAdmin)
186		b.store.preset(Secrets{AdminPassword: storedAdmin})
187		b.ip.ok = false
188		return b
189	}
190	
191	func (b *bench) run() (ProvisionResult, error) {
192		b.t.Helper()
193		ctx, cancel := context.WithTimeout(context.Background(), provisionTimeout)
194		defer cancel()
195		return Provision(ctx, b.nexus.URL(), b.ip, b.store, b.p, b.out)
196	}
197	
198	// mustRun runs Provision and fails the test on an error.
199	func (b *bench) mustRun() ProvisionResult {
200		b.t.Helper()
201		res, err := b.run()
202		if err != nil {
203			b.t.Fatalf("Provision: %v", err)
204		}
205		b.requireQuiet(nil)
206		return res
207	}
208	
209	// knownSecrets is every password the scenario handled, plus the marker.
210	func (b *bench) knownSecrets() []string {
211		set := map[string]bool{secretMarker: true, REDACTED: true, storedAdmin: true}
212		for _, s := range b.nexus.SecretsSeen() {
213			set[s] = true
214		}
215		for _, s := range b.store.values() {
216			set[s] = true
217		}
218		set[b.ip.password] = true
219		delete(set, "")
220		out := make([]string, 0, len(set))
221		for s := range set {
222			out = append(out, s)
223		}
224		return out
225	}
226	
227	// requireQuiet fails when what Provision wrote to out, or err, carries a
228	// password or the marker.
229	func (b *bench) requireQuiet(err error) {
230		b.t.Helper()
231		texts := map[string]string{"output": b.out.String()}
232		if err != nil {
233			texts["error"] = err.Error()
234		}
235		for label, text := range texts {
236			for _, secret := range b.knownSecrets() {
237				if strings.Contains(text, secret) {
238					b.t.Errorf("the %s contains a password (%d characters): %q", label, len(secret), text)
239				}
240			}
241		}
242	}
243	
244	// failure runs Provision, requires an error and checks it is quiet.
245	func (b *bench) failure() error {
246		b.t.Helper()
247		_, err := b.run()
248		if err == nil {
249			b.t.Fatal("Provision succeeded, want an error")
250		}
251		b.requireQuiet(err)
252		return err
253	}
254	
255	// requestsFrom returns the requests the fake received after the first n.
256	func (b *bench) requestsFrom(n int) []fakeReq {
257		return b.nexus.Requests()[n:]
258	}
259	
260	// writes returns "METHOD path" of the requests that are not GET.
261	func writes(reqs []fakeReq) []string {
262		var out []string
263		for _, r := range reqs {
264			if r.Method != http.MethodGet {
265				out = append(out, r.Method+" "+r.Path)
266			}
267		}
268		return out
269	}
270	
271	// posts returns "POST path" of the POST requests.
272	func posts(reqs []fakeReq) []string {
273		var out []string
274		for _, r := range reqs {
275			if r.Method == http.MethodPost {
276				out = append(out, r.Method+" "+r.Path)
277			}
278		}
279		return out
280	}
281	
282	func requireGeneratedPassword(t *testing.T, label, pw string) {
283		t.Helper()
284		if len(pw) != 32 {
285			t.Errorf("%s has %d characters, want 32", label, len(pw))
286		}
287		for _, r := range pw {
288			if !strings.ContainsRune(generatedAlphabet, r) {
289				t.Errorf("%s has the character %q outside [A-Za-z0-9]", label, r)
290				break
291			}
292		}
293		for _, banned := range []string{"admin123", "admin", REDACTED, secretMarker} {
294			if strings.Contains(pw, banned) {
295				t.Errorf("%s contains the predictable or known text %q", label, banned)
296			}
297		}
298	}
299	
300	func requireRepo(t *testing.T, f *fakeNexus, kind, name string) map[string]any {
301		t.Helper()
302		cfg, ok := f.Repo(kind, name)
303		if !ok {
304			t.Fatalf("no %s repository %q on the instance", kind, name)
305		}
306		return cfg
307	}
308	
309	func sorted(in []string) []string {
310		out := slices.Clone(in)
311		slices.Sort(out)
312		return out
313	}
