315	// ---- case 1: a fresh instance -----------------------------------------------
316	
317	func TestProvisionFreshInstance(t *testing.T) {
318		b := newBench(t)
319		res, err := b.run()
320		if err != nil {
321			t.Fatalf("Provision: %v", err)
322		}
323		b.requireQuiet(nil)
324	
325		if want := (ProvisionResult{NexusVersion: "3.98.1-01", Edition: "COMMUNITY", EULAAccepted: true}); res != want {
326			t.Errorf("result = %+v, want %+v", res, want)
327		}
328	
329		t.Run("admin password changed after it was stored", func(t *testing.T) {
330			adminNow := b.nexus.AdminPassword()
331			if adminNow == REDACTED {
332				t.Fatal("the admin password is still the initial one")
333			}
334			requireGeneratedPassword(t, "the new admin password", adminNow)
335	
336			change := b.log.index("HTTP PUT " + pathAdminPassword)
337			if change < 0 {
338				t.Fatalf("no change-password request; journal: %v", b.log.snapshot())
339			}
340			pending := b.log.indexFuncFrom(0, func(e string) bool {
341				return strings.HasPrefix(e, "STORE Save") && strings.Contains(e, " pending")
342			})
343			if pending < 0 || pending > change {
344				t.Errorf("the pending password was saved at %d, the change-password sent at %d: Save must come first; journal: %v",
345					pending, change, b.log.snapshot())
346			}
347			promoted := b.log.indexFuncFrom(change, func(e string) bool {
348				return strings.HasPrefix(e, "STORE Save") && strings.Contains(e, " admin") && !strings.Contains(e, " pending")
349			})
350			if promoted < 0 {
351				t.Errorf("the new password was never promoted to adminPassword after the change; journal: %v", b.log.snapshot())
352			}
353	
354			stored := b.store.current()
355			if stored.AdminPassword != adminNow {
356				t.Error("the stored adminPassword is not the password the instance now has")
357			}
358			if stored.PendingAdminPassword != "" {
359				t.Error("pendingAdminPassword was not cleared after the promotion")
360			}
361			for _, attempt := range b.store.attempts {
362				if attempt.PendingAdminPassword != "" && attempt.PendingAdminPassword != adminNow {
363					t.Error("the pending password saved is not the one sent to the instance")
364				}
365			}
366		})
367	
368		t.Run("EULA accepted with the disclaimer as received", func(t *testing.T) {
369			// The fake answers 400 to any other disclaimer, so accepting at all proves it.
370			if !b.nexus.EULAAccepted() {
371				t.Error("the EULA is not accepted")
372			}
373			if n := b.nexus.Count(http.MethodPost, pathEULA); n != 1 {
374				t.Errorf("POST %s sent %d times, want 1", pathEULA, n)
375			}
376		})
377	
378		t.Run("realms and anonymous access", func(t *testing.T) {
379			if got, want := b.nexus.Realms(), []string{"NexusAuthenticatingRealm", "DockerToken"}; !slices.Equal(got, want) {
380				t.Errorf("realms = %v, want %v", got, want)
381			}
382			anon := b.nexus.Anonymous()
383			if anon["enabled"] != true || anon["userId"] != "anonymous" {
384				t.Errorf("anonymous = %v, want enabled for the user anonymous", anon)
385			}
386		})
387	
388		t.Run("pull role", func(t *testing.T) {
389			role, ok := b.nexus.Role("bench-docker-pull")
390			if !ok {
391				t.Fatal("role bench-docker-pull missing")
392			}
393			want := []string{"nx-repository-view-docker-*-browse", "nx-repository-view-docker-*-read"}
394			if got := stringsAt(role, "privileges"); !slices.Equal(sorted(got), want) {
395				t.Errorf("privileges = %v, want %v", got, want)
396			}
397		})
398	
399		t.Run("pull user", func(t *testing.T) {
400			u, ok := b.nexus.User("bench-pull")
401			if !ok {
402				t.Fatal("user bench-pull missing")
403			}
404			if u.Status != "active" || !slices.Equal(u.Roles, []string{"bench-docker-pull"}) {
405				t.Errorf("bench-pull = status %q roles %v, want active with bench-docker-pull", u.Status, u.Roles)
406			}
407			requireGeneratedPassword(t, "the bench-pull password", u.Password)
408			if got := b.store.current().PullPassword; got != u.Password {
409				t.Error("the stored pullPassword is not the password of bench-pull on the instance")
410			}
411			if u.Password == b.nexus.AdminPassword() {
412				t.Error("bench-pull and admin share a password")
413			}
414			saved := b.log.indexFuncFrom(0, func(e string) bool {
415				return strings.HasPrefix(e, "STORE Save") && strings.Contains(e, " pull")
416			})
417			created := b.log.index("HTTP POST " + pathUsers)
418			if saved < 0 || created < 0 || saved > created {
419				t.Errorf("the pull password was saved at %d, the user created at %d: Save must come first; journal: %v",
420					saved, created, b.log.snapshot())
421			}
422		})
423	
424		t.Run("repositories", func(t *testing.T) {
425			for _, repo := range []struct{ kind, name string }{{"hosted", "docker-hosted"}, {"proxy", "docker-proxy"}, {"group", groupRepository}} {
426				cfg := requireRepo(t, b.nexus, repo.kind, repo.name)
427				if cfg["online"] != true || jsonAt(cfg, "storage", "blobStoreName") != "default" {
428					t.Errorf("%s: online/blob store = %v/%v, want true/default", repo.name, cfg["online"], jsonAt(cfg, "storage", "blobStoreName"))
429				}
430				if jsonAt(cfg, "docker", "forceBasicAuth") != false {
431					t.Errorf("%s: docker.forceBasicAuth = %v, want false (anonymous pull)", repo.name, jsonAt(cfg, "docker", "forceBasicAuth"))
432				}
433			}
434			proxy := requireRepo(t, b.nexus, "proxy", "docker-proxy")
435			if got := jsonAt(proxy, "proxy", "remoteUrl"); got != b.p.UpstreamURL {
436				t.Errorf("proxy.remoteUrl = %v, want %s", got, b.p.UpstreamURL)
437			}
438			if got := jsonAt(proxy, "dockerProxy", "indexType"); got != "REGISTRY" {
439				t.Errorf("dockerProxy.indexType = %v, want REGISTRY", got)
440			}
441			group := requireRepo(t, b.nexus, "group", groupRepository)
442			if got, want := stringsAt(group, "group", "memberNames"), []string{"docker-hosted", "docker-proxy"}; !slices.Equal(got, want) {
443				t.Errorf("group members = %v, want %v", got, want)
444			}
445			if got := jsonAt(group, "docker", "httpPort"); got != float64(dockerContainerPort) {
446				t.Errorf("group docker.httpPort = %v, want %d", got, dockerContainerPort)
447			}
448		})
449	}
