495	// ---- case 3: drift ----------------------------------------------------------
496	
497	func TestProvisionRestoresDrift(t *testing.T) {
498		tests := []struct {
499			name      string
500			drift     func(f *fakeNexus)
501			wantPosts []string
502		}{
503			{"group member removed", func(f *fakeNexus) {
504				f.MutateRepo("group", groupRepository, func(c map[string]any) {
505					c["group"].(map[string]any)["memberNames"] = []any{"docker-hosted"}
506				})
507			}, nil},
508			{"proxy upstream changed", func(f *fakeNexus) {
509				f.MutateRepo("proxy", "docker-proxy", func(c map[string]any) {
510					c["proxy"].(map[string]any)["remoteUrl"] = "http://elsewhere.invalid:5000"
511				})
512			}, nil},
513			{"hosted forces basic auth", func(f *fakeNexus) {
514				f.MutateRepo("hosted", "docker-hosted", func(c map[string]any) {
515					c["docker"].(map[string]any)["forceBasicAuth"] = true
516				})
517			}, nil},
518			{"group deleted", func(f *fakeNexus) { f.DeleteRepo("group", groupRepository) },
519				[]string{"POST " + repoPath("group", "")}},
520			{"proxy deleted", func(f *fakeNexus) { f.DeleteRepo("proxy", "docker-proxy") },
521				[]string{"POST " + repoPath("proxy", "")}},
522			{"role lost a privilege", func(f *fakeNexus) {
523				f.MutateRole("bench-docker-pull", func(r map[string]any) {
524					r["privileges"] = []any{"nx-repository-view-docker-*-browse"}
525				})
526			}, nil},
527			{"role deleted", func(f *fakeNexus) { f.DeleteRole("bench-docker-pull") }, []string{"POST " + pathRoles}},
528			{"user got another role", func(f *fakeNexus) {
529				f.MutateUser("bench-pull", func(u *fakeUser) { u.Roles = []string{"nx-admin"} })
530			}, nil},
531			{"user disabled", func(f *fakeNexus) {
532				f.MutateUser("bench-pull", func(u *fakeUser) { u.Status = "disabled" })
533			}, nil},
534			{"user password changed by hand", func(f *fakeNexus) {
535				f.MutateUser("bench-pull", func(u *fakeUser) { u.Password = "REDACTED" })
536			}, nil},
537			{"user deleted", func(f *fakeNexus) { f.DeleteUser("bench-pull") }, []string{"POST " + pathUsers}},
538			{"realm removed", func(f *fakeNexus) { f.SetRealms("NexusAuthenticatingRealm") }, nil},
539			{"anonymous disabled", func(f *fakeNexus) { f.SetAnonymous(false) }, nil},
540		}
541		for _, tt := range tests {
542			t.Run(tt.name, func(t *testing.T) {
543				b := newBench(t)
544				b.mustRun()
545				baseline := b.nexus.Snapshot()
546				adminBefore := b.nexus.AdminPassword()
547				b.ip.ok = false
548				tt.drift(b.nexus)
549	
550				first := len(b.nexus.Requests())
551				b.mustRun()
552	
553				if got := sorted(posts(b.requestsFrom(first))); !slices.Equal(got, sorted(tt.wantPosts)) {
554					t.Errorf("POST requests = %v, want %v", got, tt.wantPosts)
555				}
556				if after := b.nexus.Snapshot(); after != baseline {
557					t.Errorf("the drift was not repaired:\n want: %s\n got:  %s", baseline, after)
558				}
559				if got := b.nexus.AdminPassword(); got != adminBefore {
560					t.Error("the admin password changed")
561				}
562				u, _ := b.nexus.User("bench-pull")
563				if u.Password != b.store.current().PullPassword {
564					t.Error("the bench-pull password on the instance is not the stored one")
565				}
566			})
567		}
568	}
