570	// ---- case 4: the EULA -------------------------------------------------------
571	
572	func TestProvisionEULA(t *testing.T) {
573		tests := []struct {
574			name         string
575			prepare      func(b *bench)
576			wantErr      string // "" = success
577			wantCreation bool   // whether roles, users and repositories are created
578		}{
579			{
