260	// writes returns "METHOD path" of the requests that are not GET.
261	func writes(reqs []fakeReq) []string {
262		var out []string
263		for _, r := range reqs {
264			if r.Method != http.MethodGet {
265				out = append(out, r.Method+" "+r.Path)
