282	func requireGeneratedPassword(t *testing.T, label, pw string) {
283		t.Helper()
284		if len(pw) != 32 {
285			t.Errorf("%s has %d characters, want 32", label, len(pw))
286		}
287		for _, r := range pw {
288			if !strings.ContainsRune(generatedAlphabet, r) {
289				t.Errorf("%s has the character %q outside [A-Za-z0-9]", label, r)
290				break
291			}
292		}
293		for _, banned := range []string{"admin123", "admin", REDACTED, secretMarker} {
294			if strings.Contains(pw, banned) {
295				t.Errorf("%s contains the predictable or known text %q", label, banned)
296			}
297		}
298	}
