453	func TestProvisionSecondRunChangesNothing(t *testing.T) {
454		b := newBench(t)
455		b.mustRun()
456		before := b.nexus.Snapshot()
457		adminBefore := b.nexus.AdminPassword()
458		pull, _ := b.nexus.User("bench-pull")
459		storedBefore := b.store.current()
460		b.ip.ok = false // the pod file is gone after the first change
461	
462		for run := 2; run <= 3; run++ {
463			first := len(b.nexus.Requests())
464			res := b.mustRun()
465			if !res.EULAAccepted || res.NexusVersion == "" {
466				t.Errorf("run %d: result = %+v, want the version and the accepted EULA", run, res)
467			}
468			reqs := b.requestsFrom(first)
469			if got := posts(reqs); len(got) != 0 {
470				t.Errorf("run %d sent POST requests: %v", run, got)
471			}
472			if n := len(reqs); n == 0 {
473				t.Errorf("run %d sent no request at all: it cannot have read the state", run)
474			}
475			for _, w := range writes(reqs) {
476				if w == "PUT "+pathAdminPassword {
477					t.Errorf("run %d changed the admin password again", run)
478				}
479			}
480			if after := b.nexus.Snapshot(); after != before {
481				t.Errorf("run %d changed the state of the instance:\n before: %s\n after:  %s", run, before, after)
482			}
483			if got := b.nexus.AdminPassword(); got != adminBefore {
484				t.Errorf("run %d: the admin password changed", run)
485			}
486			if u, _ := b.nexus.User("bench-pull"); u.Password != pull.Password {
487				t.Errorf("run %d: the bench-pull password changed", run)
488			}
489			if got := b.store.current(); got != storedBefore {
490				t.Errorf("run %d: the stored secrets changed", run)
491			}
492		}
493	}
